"""Independent annotations of candidate control acquisitions - the E30 reference.

Why this exists: the episode estimator (mtah.acquire) is meant to replace the fixed
duration rule, so it cannot be validated against labels built by that rule - scoring it
against controlled(gt, 2 s) would grade it on how well it imitates the thing it replaces.
The semantic reference has to come from outside: a person reviewing candidate episodes on
the EXTERNAL games (never the competition match) and saying, for each one, whether control
actually changed hands, WITHOUT applying any minimum duration.

The annotation contract
-----------------------
1. Candidates are generated by mtah.acquire.propose on the clean external tracking, with
   NO duration threshold: short controls, deflections, 50/50s and bounced balls all appear.
   write_worksheet emits one row per candidate; the annotator answers the rows as given and
   does not add or delete episodes (missed candidates are a finding, to report, not to fix
   by editing the list).
2. For every row the annotator fills:
     acquired  1 if control really changed hands at this episode, 0 if not (deflection,
               rebound, duel won without control, ball back to the previous team).
     uncertain 1 whenever the reviewer cannot tell from the tracking (and the external
               video, where its licence allows looking). Uncertain rows are EXCLUDED from
               scoring - they are never counted as negatives and never "resolved" by a
               rule. Marking uncertain is a correct answer; guessing is not.
     t_start_frame  optional correction of when control began, if the proposed t_start is
               visibly off. Left blank when the proposal is right or the episode is not an
               acquisition.
     notes   free text, one line.
3. Nothing here may be derived from controlled(gt, any min_s), from the official answer
   keys, or from the challenge match: the whole point is a reference that does not come
   from the duration rule. Scripts in this file never fabricate labels; there is no
   auto-fill.
4. One worksheet per game, CSV with header:
     game,candidate_id,t0_frame,team,prev_team,acquired,uncertain,t_start_frame,notes
   team / prev_team are H or A from the acquiring side; candidate_id is the row's index in
   the worksheet, so matches stay stable if the file is re-sorted.

File layout is plain CSV so it can be reviewed in a spreadsheet; read_annotations validates
every value and refuses files with missing answers, so a half-done worksheet fails loudly
instead of silently scoring as zeros.
"""

import csv
import os

import numpy as np

COLUMNS = ["game", "candidate_id", "t0_frame", "team", "prev_team", "acquired",
           "uncertain", "t_start_frame", "notes"]
LETTERS = {1: "H", -1: "A"}


def write_worksheet(path, game, cands):
    """One row per candidate episode, answer columns blank. cands: mtah.acquire.propose
    output. The proposed t_start is carried in notes so the reviewer sees it."""
    rows = []
    for i, cand in enumerate(cands):
        rows.append(dict(game=game, candidate_id=i, t0_frame=cand["t0"],
                         team=LETTERS[cand["team"]], prev_team=LETTERS[cand["prev_team"]],
                         acquired="", uncertain=0, t_start_frame="",
                         notes="proposed_t_start={}".format(cand.get("t_start", cand["t0"]))))
    with open(path, "w", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=COLUMNS)
        writer.writeheader()
        writer.writerows(rows)
    return path


def read_annotations(path):
    """Validated answers: list of dicts. Every row must have acquired in {0, 1} and
    uncertain in {0, 1}; t_start_frame is an integer or blank. Raises ValueError on the
    first bad row - a half-filled worksheet is not a reference."""
    out = []
    with open(path, newline="") as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != COLUMNS:
            raise ValueError("{}: columns are {}, expected {}".format(
                path, reader.fieldnames, COLUMNS))
        for n, row in enumerate(reader, start=2):
            where = "{} row {}".format(path, n)
            for key in ("acquired", "uncertain"):
                if row[key] not in ("0", "1"):
                    raise ValueError("{}: {} must be 0 or 1, got {!r}".format(
                        where, key, row[key]))
            if row["team"] not in ("H", "A") or row["prev_team"] not in ("H", "A"):
                raise ValueError("{}: team letters must be H or A".format(where))
            t_start = row["t_start_frame"].strip()
            out.append(dict(game=row["game"], candidate_id=int(row["candidate_id"]),
                            t0=int(row["t0_frame"]), team=row["team"],
                            prev_team=row["prev_team"], acquired=int(row["acquired"]),
                            uncertain=int(row["uncertain"]),
                            t_start=int(t_start) if t_start else None,
                            notes=row["notes"]))
    return out


def match(cands, annotations, tol=25):
    """Pair candidates with answers by candidate_id (stable) and check the times agree
    within tol frames. Returns (pairs, missing, extra): pairs = (cand, answer) with the
    answer's candidate_id in range; missing = candidates without an answer; extra =
    answers that name no candidate. Anything in missing or extra means the worksheet and
    the candidate list have drifted apart - regenerate or re-annotate, do not average over
    it silently."""
    by_id = {a["candidate_id"]: a for a in annotations}
    pairs, missing = [], []
    for i, cand in enumerate(cands):
        ans = by_id.get(i)
        if ans is None:
            missing.append(i)
        else:
            if abs(ans["t0"] - cand["t0"]) > tol:
                raise ValueError("candidate {}: annotated t0 {} vs proposed {} - the "
                                 "worksheet does not match this candidate list".format(
                                     i, ans["t0"], cand["t0"]))
            pairs.append((cand, ans))
    extra = [i for i in by_id if i >= len(cands)]
    return pairs, missing, extra


def summarize(y, p, uncertain):
    """Plain accuracy / precision / recall at 0.5 over the CERTAIN rows only, plus the
    uncertain count. Pure numpy; no thresholds are fitted here."""
    y, p, uncertain = (np.asarray(v) for v in (y, p, uncertain))
    keep = uncertain == 0
    n_unc = int((~keep).sum())
    y, p = y[keep], p[keep]
    if len(y) == 0:
        return dict(n=0, n_uncertain=n_unc, accuracy=np.nan, precision=np.nan,
                    recall=np.nan)
    pred = p >= 0.5
    tp = int((pred & (y == 1)).sum())
    return dict(n=int(len(y)), n_uncertain=n_unc,
                accuracy=float((pred == y).mean()),
                precision=tp / max(int(pred.sum()), 1),
                recall=tp / max(int((y == 1).sum()), 1))


def load_dir(path):
    """{game: annotations} for every worksheet CSV in a directory."""
    out = {}
    for name in sorted(os.listdir(path)):
        if name.endswith(".csv"):
            rows = read_annotations(os.path.join(path, name))
            games = {r["game"] for r in rows}
            if len(games) != 1:
                raise ValueError("{}: mixes games {}".format(name, sorted(games)))
            out[games.pop()] = rows
    return out
